import{_ as o,y as s,a as i,o as a,a2 as e,D as n}from"./chunks/framework.DCcmcJcL.js";const w=JSON.parse('{"title":"Rich Snippets","description":"","frontmatter":{},"headers":[],"relativePath":"configure/rich-snippets.md","filePath":"configure/rich-snippets.md","lastUpdated":1789441803000}'),d={name:"configure/rich-snippets.md"};function c(h,t,g,p,l,u){const r=s("ImagePopup");return a(),i("div",null,[t[0]||(t[0]=e('<h1 id="rich-snippets" tabindex="-1">Rich Snippets <a class="header-anchor" href="#rich-snippets" aria-label="Permalink to &quot;Rich Snippets&quot;">​</a></h1><p>Rich snippets are structured data added to storefront pages, so search engines can show extra details, such as a product&#39;s price or rating, in their results. These settings apply to the whole store.</p><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><p>Product structured data is added to each product page. It always includes the product&#39;s name, description and link, and the switches below add more details.</p><ol><li>Go to <strong>Configure &gt;&gt; Catalog &gt;&gt; Rich Snippets</strong>.</li><li>In <strong>Products</strong>, switch <strong>Enable</strong> on.</li><li>Switch on each detail you want to include, described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),n(r,{src:"/images/configure/rich-snippets-settings.png",alt:"Products and Categories sections of the Rich Snippets screen with every switch on"}),t[1]||(t[1]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it adds</th></tr></thead><tbody><tr><td><strong>Show SKU</strong></td><td>The product&#39;s SKU.</td></tr><tr><td><strong>Show Weight</strong></td><td>The product&#39;s weight.</td></tr><tr><td><strong>Show Categories</strong></td><td>The names of the product&#39;s categories.</td></tr><tr><td><strong>Show Images</strong></td><td>Links to the product&#39;s images.</td></tr><tr><td><strong>Show Reviews</strong></td><td>The product&#39;s approved reviews, with each reviewer&#39;s name and rating.</td></tr><tr><td><strong>Show Ratings</strong></td><td>The average rating and the number of reviews.</td></tr><tr><td><strong>Show Offers</strong></td><td>The product&#39;s price, in the currency the page is shown in. For a product with options, the lowest price.</td></tr></tbody></table><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Catalog &gt;&gt; Rich Snippets</strong>.</li><li>In <strong>Categories</strong>, switch <strong>Enable</strong> on. Category pages then describe your storefront to search engines as a website.</li><li>Switch <strong>Show Search Input Field</strong> on to also describe your storefront search, so search engines can offer a search box for your store in their results.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3))])}const S=o(d,[["render",c]]);export{w as __pageData,S as default};
